private static boolean nextPermutation(int[] arr) {
    int i = arr.length - 1;
    while (i > 0 && arr[i - 1] >= arr[i]) i--;
    if (i <= 0) return false;
    int j = arr.length - 1;
    while (arr[j] <= arr[i - 1]) j--;
    int temp = arr[i - 1];
    arr[i - 1] = arr[j];
    arr[j] = temp;
    int left = i, right = arr.length - 1;
    while (left < right) {
        temp = arr[left];
        arr[left] = arr[right];
        arr[right] = temp;
        left++;
        right--;
    }
    return true;
}

