public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }

    // Find the shortest string length – no common substring can be longer
    int minLength = Integer.MAX_VALUE;
    for (String s : strings) {
        if (s == null) {
            return 0;
        }
        minLength = Math.min(minLength, s.length());
    }

    String first = strings.get(0);
    // Try lengths from longest to shortest
    for (int length = minLength; length >= 1; length--) {
        Set<String> candidates = new HashSet<>();
        // Generate all unique substrings of the specified length from the first string
        for (int i = 0; i <= first.length() - length; i++) {
            candidates.add(first.substring(i, i + length));
        }

        // Check each candidate against all strings
        Iterator<String> it = candidates.iterator();
        while (it.hasNext()) {
            String sub = it.next();
            String subRev = new StringBuilder(sub).reverse().toString();
            boolean valid = true;
            for (int idx = 1; idx < strings.size(); idx++) {
                String curr = strings.get(idx);
                if (!(curr.contains(sub) || curr.contains(subRev))) {
                    valid = false;
                    break;
                }
            }
            if (!valid) {
                it.remove(); // discard this candidate
            }
        }

        // If we have at least one valid substring of this length, return the length
        if (!candidates.isEmpty()) {
            return length;
        }
    }

    return 0;
}

