    int maxLen = first.length();

    for (int len = maxLen; len > 0; len--) {
        java.util.Set<String> subs = new java.util.HashSet<>();
        for (int i = 0; i + len <= first.length(); i++) {
            subs.add(first.substring(i, i + len));
        }

        for (String sub : subs) {
            String rev = new StringBuilder(sub).reverse().toString();
            boolean ok = true;
            for (String s : strings) {
                if (!(s.contains(sub) || s.contains(rev))) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                return len;
            }
        }
    }
    return 0;
}

