public boolean canArrange(int[] arr, int k) {
    if (arr == null || k == 0) return false;
    int n = arr.length;
    if ((n & 1) == 1) return false; // Ensure even length
    int[] count = new int[k];
    for (int num : arr) {
        int r = ((num % k) + k) % k;
        count[r]++;
    }
    if ((count[0] & 1) == 1) return false; // count of remainder 0 must be even
    if ((k & 1) == 0) { // k even
        if ((count[k / 2] & 1) == 1) return false; // remainder k/2 must be even
    }
    int limit = k / 2;
    if ((k & 1) == 0) limit = k / 2 - 1; // exclude k/2 handled separately
    for (int r = 1; r <= limit; r++) {
        if (count[r] != count[k - r]) return false;
    }
    return true;
}

