    }
    if (count[0] % 2 != 0) return false;
    for (int r = 1; r <= k / 2; r++) {
        int complement = k - r;
        if (r == complement) {
            if (count[r] % 2 != 0) return false;
        } else {
            if (count[r] != count[complement]) return false;
        }
    }
    return true;
}

