private boolean hasSubset(int[] nums, int target, int k) {
    Map<String, Boolean> memo = new HashMap<>();
    return dfs(nums, target, k, 0, memo);
}

private boolean dfs(int[] nums, int target, int k, int idx, Map<String, Boolean> memo) {
    if (k == 0) return target == 0;
    if (idx == nums.length) return false;
    String key = idx + "|" + k + "|" + target;
    if (memo.containsKey(key)) return memo.get(key);
    // Early pruning: if not enough numbers left or sum too large/small
    if (k > nums.length - idx) {
        memo.put(key, false);
        return false;
    }
    // Choose current number
    boolean taken = false;
    if (nums[idx] <= target) {
        taken = dfs(nums, target - nums[idx], k - 1, idx + 1, memo);
    }
    // Skip current number
    boolean notTaken = dfs(nums, target, k, idx + 1, memo);
    boolean result = taken || notTaken;
    memo.put(key, result);
    return result;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }

    // subsets[k] holds all possible sums using exactly k numbers
    @SuppressWarnings("unchecked")
    HashSet<Integer>[] subsets = new HashSet[n + 1];
    for (int i = 0; i <= n; i++) {
        subsets[i] = new HashSet<>();
    }
    subsets[0].add(0);

    for (int num : nums) {
        // iterate k from high to low to avoid using the same number twice
        for (int k = n - 1; k >= 1; k--) {
            if (subsets[k - 1].isEmpty()) {
                continue;
            }
            for (int prevSum : subsets[k - 1]) {
                subsets[k].add(prevSum + num);
            }
        }
    }

    for (int k = 1; k < n; k++) {
        // The target sum must be an integer
        if ((totalSum * k) % n != 0) {
            continue;
        }
        int target = (int) ((totalSum * k) / n);
        if (subsets[k].contains(target)) {
            return true;
        }
    }
    return false;
}

