    dp[1] = cost[1];
    for (int i = 2; i < n; i++) {
        dp[i] = cost[i] + Math.min(dp[i - 1], dp[i - 2]);
    }
    return Math.min(dp[n - 1], dp[n - 2]);
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    int prev1 = 0; // Minimum cost to reach step i-1
    int prev2 = 0; // Minimum cost to reach step i-2
    for (int i = 2; i <= n; i++) {
        int current = Math.min(prev1 + cost[i - 1], prev2 + cost[i - 2]);
        prev2 = prev1;
        prev1 = current;
    }
    return prev1;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    int a = cost[0];
    if (n == 1) return a;
    int b = cost[1];
    if (n == 2) return Math.min(a, b);
    for (int i = 2; i < n; i++) {
        int c = cost[i] + Math.min(a, b);
        a = b;
        b = c;
    }
    return Math.min(a, b);
}

