public boolean hasAllCodes(String s, int k) {
    if (k > s.length()) return false;
    int total = 1 << k;                     // number of possible binary strings of length k
    boolean[] seen = new boolean[total];     // track which patterns have appeared
    int mask = total - 1;                    // mask to keep only k bits
    int code = 0;                            // current sliding window as integer
    int seenCount = 0;

    for (int i = 0; i < s.length(); i++) {
        code = ((code << 1) & mask) | (s.charAt(i) - '0'); // shift left, add new bit
        if (i >= k - 1) {                      // window is fully formed
            if (!seen[code]) {
                seen[code] = true;
                seenCount++;
                if (seenCount == total) return true;  // all patterns found
            }
        }
    }
    return seenCount == total;
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || k <= 0) return true; // trivially all codes exist for k<=0
    if (s.length() < k) return false;
    int total = 1 << k; // number of possible binary strings of length k
    boolean[] seen = new boolean[total];
    int mask = 0;
    int count = 0;
    int maskLimit = total - 1; // for masking lower k bits
    // pre-fill mask for first k-1 characters
    for (int i = 0; i < k - 1; i++) {
        mask = (mask << 1) | (s.charAt(i) - '0');
    }
    int n = s.length();
    for (int i = k - 1; i < n; i++) {
        mask = ((mask << 1) | (s.charAt(i) - '0')) & maskLimit; // slide window
        if (!seen[mask]) {
            seen[mask] = true;
            count++;
            if (count == total) return true; // all codes found
        }
    }
    return false;
}

