    int seenCount = 0;
    int mask = 0;
    int maskBits = totalCodes - 1; // keep only k bits

    for (int i = 0; i < n; i++) {
        mask = ((mask << 1) & maskBits) | (s.charAt(i) - '0');
        if (i >= k - 1) {
            if (!seen[mask]) {
                seen[mask] = true;
                seenCount++;
                if (seenCount == totalCodes) return true;
            }
        }
    }
    return false;
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || s.length() < k || k < 1) {
        return false;
    }
    int total = 1 << k; // number of possible binary strings of length k
    boolean[] seen = new boolean[total];
    int curr = 0;
    // Build the first window of length k
    for (int i = 0; i < k; i++) {
        curr = (curr << 1) | (s.charAt(i) - '0');
    }
    int count = 1;
    seen[curr] = true;
    // Process remaining windows
    int mask = total - 1; // keeps only k bits
    for (int i = k; i < s.length(); i++) {
        curr = ((curr << 1) | (s.charAt(i) - '0')) & mask;
        if (!seen[curr]) {
            seen[curr] = true;
            count++;
            // optional early exit if all codes found
            if (count == total) {
                return true;
            }
        }
    }
    return count == total;
}

public boolean hasAllCodes(String s, int k) {
    if (k == 0) return true;
    int total = 1 << k;
    boolean[] seen = new boolean[total];
    int maskLimit = total - 1;
    int mask = 0;
    int count = 0;
    for (int i = 0; i < s.length(); i++) {
        mask = ((mask << 1) | (s.charAt(i) - '0')) & maskLimit;
        if (i >= k - 1) {
            if (!seen[mask]) {
                seen[mask] = true;
                if (++count == total) return true;
            }
        }
    }
    return count == total;
}

