public int minInsertions(String s) {
    int balance = 0;   // number of unmatched '('
    int insertions = 0; // number of insertions required
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else { // c == ')'
            if (balance > 0) {
                balance--;
            } else {
                // Need to insert a '(' before this ')'
                insertions++;
                // After insertion, this ')' will match the new '('
                // so balance stays 0
            }
        }
    }
    // Any remaining unmatched '(' need a ')' after them
    return insertions + balance;
}

public int minInsertions(String s) {
    int need = 0;   // number of '(' needed to match upcoming ')'
    int res = 0;    // counter for insertions

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            need++;
        } else { // c == ')'
            if (need > 0) {
                need--;   // match with a previous '('
            } else {
                res++;    // insert '(' before this ')'
            }
        }
    }
    return res + need; // need unmatched '(' require ')' insertions
}

