public int minOperations(int n) {
    int m = n / 2; // floor(n/2)
    if (n % 2 == 0) {
        return m * m;               // sum of first m odd numbers
    } else {
        return m * (m + 1);          // sum of even numbers 2,4,...,2m
    }
}

public int minOperations(int n) {
    int dCount = n / 2;          // number of elements that are below the target
    return dCount * (n - dCount); // total number of unit moves required
}

public int minOperations(int n) {
    int halfFloor = n / 2;
    int halfCeil = (n + 1) / 2;
    return halfFloor * halfCeil;
}

public int minOperations(int n) {
    int s = (n + 1) / 2;      // ceil(n/2)
    return s * (n - s);
}

