public int findMinFibonacciNumbers(int k) {
    // Generate all Fibonacci numbers up to k
    List<Integer> fibs = new ArrayList<>();
    fibs.add(1);
    fibs.add(1);
    while (true) {
        int size = fibs.size();
        int next = fibs.get(size - 1) + fibs.get(size - 2);
        if (next > k) {
            break;
        }
        fibs.add(next);
    }

    // Greedily subtract the largest Fibonacci number <= remaining sum
    int remaining = k;
    int count = 0;
    for (int i = fibs.size() - 1; i >= 0 && remaining > 0; i--) {
        int f = fibs.get(i);
        if (f <= remaining) {
            remaining -= f;
            count++;
        }
    }
    return count;
}

