public int findMinFibonacciNumbers(int k) {
    if (k == 0) return 0;
    // Generate Fibonacci numbers up to k
    java.util.List<Integer> fibs = new java.util.ArrayList<>();
    int a = 1, b = 1;
    fibs.add(a); // F1
    while (b <= k) {
        fibs.add(b); // F2 onward
        int next = a + b;
        a = b;
        b = next;
    }
    int count = 0;
    // Greedy: repeatedly subtract the largest Fibonacci number <= remaining k
    while (k > 0) {
        for (int i = fibs.size() - 1; i >= 0; i--) {
            int f = fibs.get(i);
            if (f <= k) {
                k -= f;
                count++;
                break; // start again with the largest
            }
        }
    }
    return count;
}

