    // Greedy selection of the largest Fibonacci number <= remaining k
    for (int i = fib.size() - 1; i >= 0 && k > 0; i--) {
        if (fib.get(i) <= k) {
            k -= fib.get(i);
            count++;
            // Continue searching again from the largest Fibonacci number (allowing repeated use)
        }
    }
    return count;
}

public int kthFactor(int n, int k) {
    ArrayList<Integer> divisors = new ArrayList<>();
    int sqrt = (int) Math.sqrt(n);
    for (int i = 1; i <= sqrt; i++) {
        if (n % i == 0) {
            divisors.add(i);
            if (i != n / i) {
                divisors.add(n / i);
            }
        }
    }
    Collections.sort(divisors);
    if (divisors.size() < k) {
        return -1;
    } else {
        return divisors.get(k - 1);
    }
}

public int kthFactor(int n, int k) {
    List<Integer> factors = new java.util.ArrayList<>();
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            factors.add(i);
            int other = n / i;
            if (other != i) {
                factors.add(other);
            }
        }
    }
    java.util.Collections.sort(factors);
    return factors.size() < k ? -1 : factors.get(k - 1);
}

public int kthFactor(int n, int k) {
    java.util.List<Integer> small = new java.util.ArrayList<>();
    java.util.List<Integer> large = new java.util.ArrayList<>();
    int sqrt = (int)Math.sqrt(n);
    for (int i = 1; i <= sqrt; i++) {
        if (n % i == 0) {
            small.add(i);
            int d = n / i;
            if (d != i) {
                large.add(d);
            }
        }
    }
    java.util.List<Integer> all = new java.util.ArrayList<>(small.size() + large.size());
    all.addAll(small);
    for (int i = large.size() - 1; i >= 0; i--) {
        all.add(large.get(i));
    }
    return (k <= all.size()) ? all.get(k - 1) : -1;
}

public int kthFactor(int n, int k) {
    java.util.ArrayList<Integer> small = new java.util.ArrayList<>();
    java.util.ArrayList<Integer> large = new java.util.ArrayList<>();

    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            small.add(i);
            int other = n / i;
            if (other != i) {
                large.add(other);
            }
        }
    }

    int total = small.size() + large.size();
    if (k > total) {
        return -1;
    }

    if (k <= small.size()) {
        return small.get(k - 1);
    } else {
        int idx = k - small.size() - 1; // 0-based index in ascending order of large factors
        int reverseIdx = large.size() - 1 - idx; // convert to index in stored descending list
        return large.get(reverseIdx);
    }
}

public int kthFactor(int n, int k) {
    int limit = (int) Math.sqrt(n);
    int[] small = new int[limit + 1];
    int[] large = new int[limit + 1];
    int sSize = 0, lSize = 0;

    for (int i = 1; i <= limit; i++) {
        if (n % i == 0) {
            small[sSize++] = i;
            if (i != n / i) {
                large[lSize++] = n / i;
            }
        }
    }

    int total = sSize + lSize;
    if (k > total) return -1;
    if (k <= sSize) return small[k - 1];
    int remaining = k - sSize;
    return large[lSize - remaining];
}

