    dfs(s, 0, used, max);
    return max[0];
}

private void dfs(String s, int index, java.util.Set<String> used, int[] max) {
    if (index == s.length()) {
        if (used.size() > max[0]) {
            max[0] = used.size();
        }
        return;
    }
    for (int end = index + 1; end <= s.length(); end++) {
        String part = s.substring(index, end);
        if (!used.contains(part)) {
            used.add(part);
            dfs(s, end, used, max);
            used.remove(part);
        }
    }
}

