private int dfs(int idx, java.util.HashSet<String> used, String s) {
    if (idx == s.length()) {
        return 0;
    }
    int best = 0;
    for (int end = idx + 1; end <= s.length(); end++) {
        String part = s.substring(idx, end);
        if (!used.contains(part)) {
            used.add(part);
            int count = 1 + dfs(end, used, s);
            if (count > best) {
                best = count;
            }
            used.remove(part);
        }
    }
    return best;
}

