        void dfs(int pos, java.util.Set<String> used, int count) {
            if (pos == n) {
                if (count > max[0]) {
                    max[0] = count;
                }
                return;
            }
            for (int end = pos + 1; end <= n; end++) {
                String sub = s.substring(pos, end);
                if (!used.contains(sub)) {
                    used.add(sub);
                    dfs(end, used, count + 1);
                    used.remove(sub);
                }
            }
        }
    }

