public String getSmallestString(int n, int k) {
    char[] ans = new char[n];
    int surplus = k - n; // extra value beyond all 'a's
    for (int i = n - 1; i >= 0 && surplus > 0; i--) {
        int add = Math.min(25, surplus);
        ans[i] = (char) ('a' + add);
        surplus -= add;
    }
    for (int i = 0; i < n; i++) {
        if (ans[i] == 0) ans[i] = 'a';
    }
    return new String(ans);
}

