public static int singleNumber(int[] nums) {
    int[] bits = new int[32];
    for (int num : nums) {
        for (int i = 0; i < 32; i++) {
            if (((num >> i) & 1) != 0) {
                bits[i]++;
            }
        }
    }
    int result = 0;
    for (int i = 0; i < 32; i++) {
        if (bits[i] % 3 != 0) {
            result |= (1 << i);
        }
    }
    return result;
}

