public static int singleNumber(int[] nums) {
    int ones = 0, twos = 0;
    for (int num : nums) {
        // The new twos becomes the bits that have appeared twice
        twos |= (ones & num);
        // The new ones becomes the bits that have appeared once
        ones ^= num;
        // mask bits that have appeared three times
        int mask = ~(ones & twos);
        ones &= mask;
        twos &= mask;
    }
    return ones;
}

