public static List<Integer> findSteppingNumbers(int low, int high) {
    // Use a TreeSet to keep results sorted and avoid duplicates
    java.util.Set<Integer> resultSet = new java.util.TreeSet<>();

    // 0 is a stepping number only if it is within the range
    if (low <= 0 && 0 <= high) {
        resultSet.add(0);
    }

    // Use BFS starting from digits 1-9
    java.util.Queue<Long> queue = new java.util.LinkedList<>();
    for (int i = 1; i <= 9; i++) {
        queue.offer((long) i);
    }

    while (!queue.isEmpty()) {
        long num = queue.poll();
        if (num > high) {
            continue; // all children will be larger, stop exploring this branch
        }

        int intNum = (int) num;
        if (intNum >= low && intNum <= high) {
            resultSet.add(intNum);
        }

        long lastDigit = num % 10;
        if (lastDigit > 0) {
            long next = num * 10 + (lastDigit - 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
        if (lastDigit < 9) {
            long next = num * 10 + (lastDigit + 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
    }

    return new java.util.ArrayList<>(resultSet);
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low == 0) {
        if (high >= 0) result.add(0);
    }
    Queue<Long> queue = new LinkedList<>();
    for (int i = 1; i <= 9; i++) {
        queue.offer((long) i);
    }
    while (!queue.isEmpty()) {
        long num = queue.poll();
        if (num > high) continue;
        if (num >= low) result.add((int) num);
        long last = num % 10;
        if (last > 0) {
            long next = num * 10 + (last - 1);
            if (next <= high) queue.offer(next);
        }
        if (last < 9) {
            long next = num * 10 + (last + 1);
            if (next <= high) queue.offer(next);
        }
    }
    Collections.sort(result);
    return result;
}

public static int countDigitOne(int n) {
    long count = 0;
    long factor = 1;
    while (factor <= n) {
        long lower = n % factor;
        long current = (n / factor) % 10;
        long higher = n / (factor * 10);

        if (current == 0) {
            count += higher * factor;
        } else if (current == 1) {
            count += higher * factor + lower + 1;
        } else {
            count += (higher + 1) * factor;
        }

        factor *= 10;
    }
    return (int) count;
}

