public static String addThousandSeparator(int n) {
    if (n == 0) return "0";
    boolean negative = n < 0;
    long num = n;
    if (num < 0) num = -num;
    StringBuilder sb = new StringBuilder();
    int count = 0;
    while (num > 0) {
        sb.append(num % 10);
        num /= 10;
        count++;
        if (num > 0 && count % 3 == 0) sb.append('.');
    }
    sb.reverse();
    String result = sb.toString();
    if (negative) result = "-" + result;
    return result;
}

public static String addThousandSeparator(int n) {
