    boolean negative = s.startsWith("-");
    if (negative) {
        s = s.substring(1);
    }
    StringBuilder sb = new StringBuilder();
    int count = 0;
    for (int i = s.length() - 1; i >= 0; i--) {
        sb.append(s.charAt(i));
        count++;
        if (count == 3 && i != 0) {
            sb.append('.');
            count = 0;
        }
    }
    sb.reverse();
    if (negative) {
        sb.insert(0, '-');
    }
    return sb.toString();
}

