public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    // Build count map
    java.util.Map<Integer,Integer> countMap = new java.util.HashMap<>();
    int maxVal = 0;
    for (int v : A) {
        countMap.put(v, countMap.getOrDefault(v, 0) + 1);
        if (v > maxVal) maxVal = v;
    }
    // Precompute possible sums up to 2*maxVal
    int maxSum = 2 * maxVal;
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int i = 0; i * i <= maxSum; ++i) isSquare[i * i] = true;

    java.util.List<Integer> uniqueVals = new java.util.ArrayList<>(countMap.keySet());
    java.util.Collections.sort(uniqueVals);

    int[] result = new int[1];
    java.util.function.Consumer<Integer> dfs = new java.util.function.Consumer<Integer>() {
        @Override
        public void accept(Integer prev) {
            boolean finished = true;
            for (int val : uniqueVals) {
                int cnt = countMap.getOrDefault(val, 0);
                if (cnt == 0) continue;
                if (prev == null || isSquare[prev + val]) {
                    finished = false;
                    countMap.put(val, cnt - 1);
                    if (cnt - 1 == 0) countMap.remove(val);
                    dfs.accept(val);
                    // backtrack
                    if (countMap.containsKey(val)) {
                        countMap.put(val, countMap.get(val) + 1);
                    } else {
                        countMap.put(val, 1);
                    }
                }
            }
            if (finished) {
                result[0] += 1;
            }
        }
    };

    dfs.accept(null);
    return result[0];
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    int[] arr = A.clone();
    java.util.Arrays.sort(arr);
    boolean[] used = new boolean[n];
    return backtrack(arr, used, 0, -1);
}

private static int backtrack(int[] arr, boolean[] used, int idx, int prev) {
    int n = arr.length;
    if (idx == n) return 1;
    int count = 0;
    for (int i = 0; i < n; i++) {
        if (used[i]) continue;
        if (idx > 0 && !isSquare(arr[i] + prev)) continue;
        if (i > 0 && arr[i] == arr[i - 1] && !used[i - 1]) continue;
        used[i] = true;
        count += backtrack(arr, used, idx + 1, arr[i]);
        used[i] = false;
    }
    return count;
}

private static boolean isSquare(int sum) {
    int root = (int) Math.sqrt(sum);
    return root * root == sum;
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    Map<Integer, Integer> freq = new HashMap<>();
    for (int x : A) {
        freq.put(x, freq.getOrDefault(x, 0) + 1);
    }

    int maxVal = 0;
    for (int x : A) if (x > maxVal) maxVal = x;
    int maxSum = 2 * maxVal;
    Set<Integer> squareSet = new HashSet<>();
    for (int i = 2; i * i <= maxSum; i++) squareSet.add(i * i);

    Map<String, Integer> memo = new HashMap<>();

    // Helper to generate a string key based on current freq map
    java.util.function.Function<Map<Integer, Integer>, String> freqKey = (m) -> {
        StringBuilder sb = new StringBuilder();
        m.keySet().stream().sorted().forEach(k -> sb.append(k).append(':').append(m.get(k)).append(';'));
        return sb.toString();
    };

    java.util.function.Function<Map<Integer, Integer>, Integer> remainingCount = (m) -> m.values().stream().mapToInt(Integer::intValue).sum();

    // DFS that returns count of valid permutations from current state
    java.util.function.BiFunction<Map<Integer, Integer>, Integer, Integer> dfs = new java.util.function.BiFunction<>() {
        @Override
        public Integer apply(Map<Integer, Integer> curFreq, Integer last) {
            String key = last + "|" + freqKey.apply(curFreq);
            if (memo.containsKey(key)) return memo.get(key);
            if (remainingCount.apply(curFreq) == 0) return 1; // all used
            int total = 0;
            for (Map.Entry<Integer, Integer> entry : curFreq.entrySet()) {
                int val = entry.getKey();
                int cnt = entry.getValue();
                if (cnt == 0) continue;
                if (last == null || squareSet.contains(last + val)) {
                    curFreq.put(val, cnt - 1);
                    total += apply(curFreq, val);
                    curFreq.put(val, cnt);
                }
            }
            memo.put(key, total);
            return total;
        }
    };

    return dfs.apply(freq, null);
}

public static int largestRectangleArea(int[] heights) {
    int n = heights.length;
    int maxArea = 0;
    int[] stack = new int[n + 1];
    int top = -1;

    for (int i = 0; i <= n; i++) {
        int curHeight = (i == n) ? 0 : heights[i];
        while (top >= 0 && heights[stack[top]] > curHeight) {
            int height = heights[stack[top--]];
            int width = (top == -1) ? i : i - stack[top] - 1;
            int area = height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack[++top] = i;
    }

    return maxArea;
}

public static int largestRectangleArea(int[] heights) {
