    int len = digits.length;

    // Find the first index i where digits[i] < digits[i + 1] from the right
    int i = len - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) {
        return -1; // No higher permutation exists
    }

