public static List<String> centerSymmetricNumbers(int n) {
    List<String> res = new ArrayList<>();
    if (n == 0) {
        return res;
    }
    char[][] pairs = {{'0','0'}, {'1','1'}, {'6','9'}, {'8','8'}, {'9','6'}};
    char[] mid = {'0','1','8'};
    char[] curr = new char[n];
    generate(0, n - 1, curr, res, pairs, mid);
    return res;
}

private static void generate(int left, int right, char[] curr, List<String> res, char[][] pairs, char[] mid) {
    if (left > right) {
        res.add(new String(curr));
        return;
    }
    if (left == right) {
        for (char c : mid) {
            curr[left] = c;
