    if (n <= 0) return 0;
    int[] ugly = new int[n];
    ugly[0] = 1;
    int idx2 = 0, idx3 = 0, idx5 = 0;
    int next2 = 2, next3 = 3, next5 = 5;
    for (int i = 1; i < n; i++) {
        int nextUgly = Math.min(next2, Math.min(next3, next5));
        ugly[i] = nextUgly;
        if (nextUgly == next2) {
            idx2++;
            next2 = ugly[idx2] * 2;
        }
        if (nextUgly == next3) {
            idx3++;
            next3 = ugly[idx3] * 3;
        }
        if (nextUgly == next5) {
            idx5++;
            next5 = ugly[idx5] * 5;
        }
    }
    return ugly[n - 1];
}

