public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    ArrayDeque<Long> stack = new ArrayDeque<>();
    for (int i = 9; i >= 1 && i <= n; i--) {
        stack.push((long) i);
    }
    while (!stack.isEmpty()) {
        long curr = stack.pop();
        if (curr > n) {
            continue;
        }
        result.add((int) curr);
        for (int i = 9; i >= 0; i--) {
            stack.push(curr * 10 + i);
        }
    }
    return result;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    int cur = 1;
    for (int i = 0; i < n; i++) {
        result.add(cur);
        if (cur * 10 <= n) {
            cur *= 10;
        } else {
            if (cur % 10 != 9 && cur + 1 <= n) {
                cur++;
            } else {
                while ((cur / 10) % 10 == 9 || cur / 10 + 1 > n) {
                    cur /= 10;
                }
                cur = cur / 10 + 1;
            }
        }
    }
    return result;
}

