public static int calculateUniqueSum(int[] nums) {
    java.util.HashSet<Integer> seen = new java.util.HashSet<>();
    java.util.HashSet<Integer> duplicates = new java.util.HashSet<>();
    for (int num : nums) {
        if (!seen.add(num)) { // add returns false if already present
            duplicates.add(num);
        }
    }
    int sum = 0;
    for (int num : seen) {
        if (!duplicates.contains(num)) {
            sum += num;
        }
    }
    return sum;
}

