public static int minPerfectSquareSum(int n) {
    if (n <= 0) return 0;
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        int min = Integer.MAX_VALUE;
        int j = 1;
        while (j * j <= i) {
            int candidate = dp[i - j * j] + 1;
            if (candidate < min) {
                min = candidate;
            }
            j++;
        }
        dp[i] = min;
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    for (int i = 0; i <= n; i++) {
        dp[i] = i; // maximum number of squares (all ones)
    }
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            dp[i] = Math.min(dp[i], dp[i - square] + 1);
        }
    }
    return dp[n];
}

